const loads=new Map();async function lib(name){if(!loads.has(name))loads.set(name,new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=new URL('./vendor/'+name,import.meta.url).href;s.onload=resolve;s.onerror=()=>reject(Error('Falha ao carregar gerador de documentos.'));document.head.append(s);}));return loads.get(name);}
const bytes=f=>Uint8Array.from(atob(f.base64),c=>c.charCodeAt(0));async function docxData(data){await lib('jszip.min.js');const zip=await window.JSZip.loadAsync(data);if(!zip.file('word/document.xml'))throw Error('DOCX inválido.');if(Object.values(zip.files).reduce((s,f)=>s+(f._data?.uncompressedSize||0),0)>20*1024*1024)throw Error('DOCX muito grande após descompactar.');return zip;}
export async function validateLetterhead(file){if(file.mime.includes('wordprocessingml'))return docxData(bytes(file));if(file.mime==='application/pdf'){await lib('pdf-lib.min.js');return window.PDFLib.PDFDocument.load(bytes(file));}if(!['image/png','image/jpeg'].includes(file.mime))throw Error('Formato inválido.');}
async function docxPng(data){await docxData(data);await lib('docx-preview.min.js');await lib('html2canvas.min.js');const host=document.createElement('div');host.style.cssText='position:fixed;left:-15000px;top:0;background:white;';document.body.append(host);try{await window.docx.renderAsync(data,host,undefined,{inWrapper:false,ignoreFonts:true,useBase64URL:true,renderHeaders:true,renderFooters:true});const page=host.querySelector('article');if(!page)throw Error('Papel DOCX não renderizado.');await document.fonts.ready;const canvas=await window.html2canvas(page,{scale:1.5,logging:false,backgroundColor:'#fff',allowTaint:false});return Uint8Array.from(atob(canvas.toDataURL('image/png').split(',')[1]),c=>c.charCodeAt(0));}finally{host.remove();}}
export async function createWarningPdf(doc,file){await lib('pdf-lib.min.js');await lib('fontkit.min.js');const P=window.PDFLib,pdf=await P.PDFDocument.create();pdf.registerFontkit(window.fontkit);const font=await pdf.embedFont(await fetch(new URL('./vendor/DejaVuSans.ttf',import.meta.url)).then(r=>r.arrayBuffer()),{subset:true});let w=595.28,h=841.89,bg=null;if(file){const data=bytes(file);if(file.mime==='application/pdf'){const source=await P.PDFDocument.load(data);({width:w,height:h}=source.getPage(0).getSize());bg={page:(await pdf.embedPdf(source,[0]))[0]};}else bg={image:file.mime==='image/jpeg'?await pdf.embedJpg(data):await pdf.embedPng(file.mime.includes('wordprocessingml')?await docxPng(data):data)};}const m=72/25.4,l=doc.layout||{top:35,bottom:30,left:20,right:20,fontSize:11},size=l.fontSize||11,width=w-(l.left+l.right)*m,lines=[];for(const para of[doc.header,doc.body,doc.footer].join('\n\n').replace(/\r/g,'').split('\n')){let line='';for(const word of para.split(/\s+/)){const next=line?line+' '+word:word;if(font.widthOfTextAtSize(next,size)<=width)line=next;else{if(line)lines.push(line);line='';for(const ch of word){if(line&&font.widthOfTextAtSize(line+ch,size)>width){lines.push(line);line='';}line+=ch;}}}lines.push(line);}const count=Math.floor((h-(l.top+l.bottom)*m)/(size*1.45));if(count<3)throw Error('Margens grandes para este papel.');for(let i=0;i<Math.max(1,lines.length);i+=count){const page=pdf.addPage([w,h]);if(bg?.page)page.drawPage(bg.page,{x:0,y:0,width:w,height:h});if(bg?.image){const ratio=Math.min(w/bg.image.width,h/bg.image.height),iw=bg.image.width*ratio,ih=bg.image.height*ratio;page.drawImage(bg.image,{x:(w-iw)/2,y:(h-ih)/2,width:iw,height:ih});}lines.slice(i,i+count).forEach((text,n)=>{if(text)page.drawText(text,{x:l.left*m,y:h-l.top*m-size-n*size*1.45,size,font});});}return new Blob([await pdf.save()],{type:'application/pdf'});}
